//! Themes: the 48 lvim-colorscheme styles, as data.
//!
//! A theme is a TOML file generated by lvim-colorscheme (`scripts/build lode`,
//! output in `extras/lode/`). Nothing about a theme is code here — the file
//! names the surfaces, the inks and the accents, and this module copies them
//! into egui's `Style`. Adding a 49th palette means generating one more file.
//!
//! **The file is the editor's own colours.** The generator reads lvim-colorscheme's
//! RESOLVED HIGHLIGHT GROUPS — `Normal`, `NormalSB`, `Pmenu`, `NormalFloat`,
//! `StatusLine`, `CursorLine`, `PmenuSel`, `Visual`, `TabLine`, `Comment` and the
//! rest — and copies them unchanged, including the pairs that measure below
//! 4.5:1. `Normal.fg` on base dark is `#5e8888` at 3.86:1 and arrives here as
//! `#5e8888`.
//!
//! So nothing in this module adjusts a colour, and nothing may start to. A client
//! that "improved" a theme would stop being the same colour as the editor beside
//! it, which is the entire reason the theme is read from the editor's groups.
//!
//! Themes are searched for in `$LODE_THEME_DIR`, then `$XDG_CONFIG_HOME/lode/themes`,
//! then `~/.config/lode/themes`. With no theme files at all the built-in
//! fallback applies, so a fresh install is usable before anything is generated.

use std::collections::BTreeMap;
use std::path::PathBuf;

use serde::Deserialize;

/// One theme file.
///
/// The whole file is read, including roles this version does not paint with yet
/// — the editor has no syntax highlighting, so `[syntax]` is parsed and held
/// rather than used, and `[palette]` is reference data by design. They are kept
/// because the FILE is the contract: a client that silently dropped a role
/// would make the generator's output and the client's idea of a theme drift
/// apart, and the test that loads all 48 real files checks what it parses, not
/// what this version happens to draw.
#[allow(dead_code)]
#[derive(Debug, Clone, Deserialize)]
pub struct Theme {
    pub name: String,
    #[serde(default)]
    pub style: String,
    #[serde(default)]
    pub dark: bool,
    pub surface: Surface,
    pub text: Text,
    pub accent: Accent,
    #[serde(default)]
    pub syntax: Syntax,
    #[serde(default, rename = "match")]
    pub match_: Match,
    pub grid: Grid,
    /// The raw palette, carried verbatim for reference. NOT grounded and not
    /// drawn with — see the generator's note.
    #[serde(default)]
    pub palette: BTreeMap<String, String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Surface {
    /// The main working surface: the editor body and the grid.
    pub base: String,
    /// Side panels and the connection list.
    pub panel: String,
    /// A card, a selected row, a header strip.
    pub raised: String,
    /// Popups and dialogs.
    pub overlay: String,
    /// The strip along the bottom edge. Deeper than `panel`, so it reads as the
    /// window's edge rather than as one more panel.
    #[serde(default)]
    pub status: String,
    /// The row under the pointer — the editor's `CursorLine`.
    #[serde(default)]
    pub hover: String,
    /// A selected entry in a LIST — the editor's `PmenuSel`. Distinct from
    /// `grid.selection_bg`, which is selected TEXT (`Visual`); the editor draws
    /// those two differently and so does this.
    #[serde(default)]
    pub selected: String,
    /// The editor's `WinSeparator`. On every lvim style it equals its own
    /// background — the editor draws no line between windows — so frames here
    /// are invisible and the structure is carried by the surfaces. That is the
    /// editor's look, copied, not an omission.
    pub border: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Text {
    pub primary: String,
    /// `Comment`, deliberately not `LineNr`: both are quiet in the editor and
    /// they are not interchangeable. A gutter number is meant to be nearly
    /// invisible; a section heading is meant to be read.
    pub muted: String,
    /// `Title` — section headings.
    #[serde(default)]
    pub title: String,
    /// Ink drawn ON an accent — a button label, a badge.
    pub inverted: String,
}

#[allow(dead_code)] // see the note on `Theme`: the file is the contract
#[derive(Debug, Clone, Deserialize)]
pub struct Accent {
    pub primary: String,
    pub secondary: String,
    pub success: String,
    pub warning: String,
    pub error: String,
    pub info: String,
}

#[allow(dead_code)] // see the note on `Theme`: the file is the contract
#[derive(Debug, Clone, Default, Deserialize)]
pub struct Syntax {
    #[serde(default)]
    pub keyword: String,
    #[serde(default)]
    pub string: String,
    #[serde(default)]
    pub number: String,
    #[serde(default)]
    pub comment: String,
    #[serde(default)]
    pub function: String,
    #[serde(default)]
    pub operator: String,
    #[serde(default)]
    pub identifier: String,
}

#[allow(dead_code)] // see the note on `Theme`: the file is the contract
#[derive(Debug, Clone, Deserialize)]
pub struct Grid {
    pub header_bg: String,
    pub header_fg: String,
    /// Every other row, for tracking a long line across the width.
    pub row_alt: String,
    pub selection_bg: String,
    pub selection_fg: String,
    /// SQL NULL. A different colour, never the word in the same ink — a NULL and
    /// a string reading "NULL" are different values and must not look alike.
    pub null_fg: String,
    /// `LineNr` — the row-number column and nothing else. The one thing in this
    /// client that is literally a line number, and as quiet as the editor's
    /// gutter is.
    #[serde(default)]
    pub line_nr: String,
}

/// A search match — `Search` / `IncSearch`. Carried though the client does not
/// paint with it yet, for the same reason `[syntax]` is: the file is the
/// contract, and a role dropped because today's client has no use for it is a
/// role the next version has to re-derive from somewhere else.
#[allow(dead_code)] // see the note on `Theme`: the file is the contract
#[derive(Debug, Clone, Default, Deserialize)]
pub struct Match {
    #[serde(default)]
    pub bg: String,
    #[serde(default)]
    pub fg: String,
}

/// Parse `#rrggbb` (or `rrggbb`). An unparseable colour falls back to the given
/// default rather than failing the theme: one bad line should cost one colour.
pub fn hex(s: &str, fallback: egui::Color32) -> egui::Color32 {
    let s = s.trim().trim_start_matches('#');
    if s.len() != 6 {
        return fallback;
    }
    match (
        u8::from_str_radix(&s[0..2], 16),
        u8::from_str_radix(&s[2..4], 16),
        u8::from_str_radix(&s[4..6], 16),
    ) {
        (Ok(r), Ok(g), Ok(b)) => egui::Color32::from_rgb(r, g, b),
        _ => fallback,
    }
}

impl Theme {
    pub fn c(&self, s: &str, fallback: egui::Color32) -> egui::Color32 {
        hex(s, fallback)
    }

    /// The named surfaces, resolved. Every one falls back to a surface that is
    /// certainly there, so a theme missing a role is dimmer, never broken.
    pub fn base(&self) -> egui::Color32 {
        self.c(&self.surface.base, egui::Color32::from_rgb(0x20, 0x27, 0x2b))
    }
    pub fn panel(&self) -> egui::Color32 {
        self.c(&self.surface.panel, self.base())
    }
    pub fn raised(&self) -> egui::Color32 {
        self.c(&self.surface.raised, self.base())
    }
    pub fn overlay(&self) -> egui::Color32 {
        self.c(&self.surface.overlay, self.panel())
    }
    /// The status strip. A theme generated before this role existed has no
    /// `status`, and the panel is the honest stand-in.
    pub fn status(&self) -> egui::Color32 {
        self.c(&self.surface.status, self.panel())
    }
    pub fn hover(&self) -> egui::Color32 {
        self.c(&self.surface.hover, self.raised())
    }
    pub fn selected(&self) -> egui::Color32 {
        self.c(&self.surface.selected, self.hover())
    }
    pub fn border(&self) -> egui::Color32 {
        self.c(&self.surface.border, egui::Color32::GRAY)
    }
    pub fn fg(&self) -> egui::Color32 {
        self.c(&self.text.primary, egui::Color32::WHITE)
    }
    pub fn muted(&self) -> egui::Color32 {
        self.c(&self.text.muted, egui::Color32::GRAY)
    }
    pub fn title(&self) -> egui::Color32 {
        self.c(&self.text.title, self.muted())
    }
    pub fn inverted(&self) -> egui::Color32 {
        self.c(&self.text.inverted, egui::Color32::BLACK)
    }
    pub fn accent(&self) -> egui::Color32 {
        self.c(&self.accent.primary, egui::Color32::LIGHT_BLUE)
    }
    pub fn warning(&self) -> egui::Color32 {
        self.c(&self.accent.warning, egui::Color32::YELLOW)
    }
    pub fn error(&self) -> egui::Color32 {
        self.c(&self.accent.error, egui::Color32::RED)
    }
    pub fn success(&self) -> egui::Color32 {
        self.c(&self.accent.success, self.accent())
    }
    pub fn header_bg(&self) -> egui::Color32 {
        self.c(&self.grid.header_bg, self.raised())
    }
    pub fn header_fg(&self) -> egui::Color32 {
        self.c(&self.grid.header_fg, self.fg())
    }
    pub fn null_fg(&self) -> egui::Color32 {
        self.c(&self.grid.null_fg, self.muted())
    }
    pub fn line_nr(&self) -> egui::Color32 {
        self.c(&self.grid.line_nr, self.muted())
    }
    pub fn selection_bg(&self) -> egui::Color32 {
        self.c(&self.grid.selection_bg, self.selected())
    }
    pub fn selection_fg(&self) -> egui::Color32 {
        self.c(&self.grid.selection_fg, self.fg())
    }

    /// Paint this theme onto an egui context: colours, AND the metrics.
    ///
    /// The metrics used to be left at egui's defaults, on the argument that a
    /// palette is not a layout. That argument was right about the FILE and wrong
    /// about the application: nothing in the theme file describes spacing, and
    /// the result was a correct palette poured into a toolkit demo — controls
    /// touching each other, no margins, one text size for everything. The
    /// metrics belong to the application, so they are set here, once, and are
    /// the same whichever of the 48 palettes is loaded. Switching a theme still
    /// changes no measurement.
    ///
    /// `scale` is the base text size, from `$LODE_FONT_SIZE`; everything else is
    /// derived from it so one number moves the whole interface.
    pub fn apply(&self, ctx: &egui::Context, scale: f32) {
        let base = self.base();
        let panel = self.panel();
        let raised = self.raised();
        let overlay = self.overlay();
        let border = self.border();
        let fg = self.fg();
        let muted = self.muted();
        let primary = self.accent();
        let inverted = self.inverted();
        let hover = self.hover();

        let mut v = if self.dark {
            egui::Visuals::dark()
        } else {
            egui::Visuals::light()
        };
        v.dark_mode = self.dark;
        v.panel_fill = panel;
        v.window_fill = overlay;
        v.extreme_bg_color = base;
        v.faint_bg_color = self.c(&self.grid.row_alt, raised);
        v.code_bg_color = base;
        v.window_stroke = egui::Stroke::new(1.0_f32, border);
        // A selected entry in a LIST: the editor's `PmenuSel`. The grid's own
        // selected row is `Visual` and is painted by the grid, because egui has
        // one selection colour and the editor has two different ones.
        v.selection.bg_fill = self.selected();
        v.selection.stroke = egui::Stroke::new(1.0_f32, fg);
        v.hyperlink_color = primary;
        v.warn_fg_color = self.c(&self.accent.warning, egui::Color32::YELLOW);
        v.error_fg_color = self.c(&self.accent.error, egui::Color32::RED);

        v.widgets.noninteractive.bg_fill = panel;
        v.widgets.noninteractive.weak_bg_fill = panel;
        v.widgets.noninteractive.bg_stroke = egui::Stroke::new(1.0_f32, border);
        v.widgets.noninteractive.fg_stroke = egui::Stroke::new(1.0_f32, muted);

        v.widgets.inactive.bg_fill = raised;
        v.widgets.inactive.weak_bg_fill = raised;
        v.widgets.inactive.bg_stroke = egui::Stroke::new(1.0_f32, border);
        v.widgets.inactive.fg_stroke = egui::Stroke::new(1.0_f32, fg);

        // A hover tints the OUTLINE, not the fill. `text.inverted` is grounded
        // against `accent.primary` and against nothing else, so filling a
        // hovered widget with `accent.secondary` and writing inverted ink on it
        // would be using a pair nobody measured — across the 48 generated
        // styles that pair falls as low as 1.78:1. The accent stays on the
        // border, where contrast is not a legibility question.
        v.widgets.hovered.bg_fill = raised;
        v.widgets.hovered.weak_bg_fill = raised;
        v.widgets.hovered.bg_stroke = egui::Stroke::new(1.0_f32, primary);
        v.widgets.hovered.fg_stroke = egui::Stroke::new(1.0_f32, fg);

        v.widgets.active.bg_fill = primary;
        v.widgets.active.weak_bg_fill = primary;
        v.widgets.active.bg_stroke = egui::Stroke::new(1.0_f32, primary);
        v.widgets.active.fg_stroke = egui::Stroke::new(1.0_f32, inverted);

        v.widgets.open.bg_fill = raised;
        v.widgets.open.weak_bg_fill = raised;
        v.widgets.open.bg_stroke = egui::Stroke::new(1.0_f32, border);
        v.widgets.open.fg_stroke = egui::Stroke::new(1.0_f32, fg);

        // A list entry or a tree row under the pointer. egui draws that with
        // `hovered.weak_bg_fill`, which is why the theme's hover surface is a
        // role and not a shade computed here.
        v.widgets.hovered.weak_bg_fill = hover;

        // ── shape ───────────────────────────────────────────────────────────
        // SQUARE. Every corner, everywhere: buttons, fields, panels, dialogs,
        // dropdowns, tabs. A terminal editor has no rounded anything, and this
        // client is meant to sit beside one and look like it does. The air comes
        // from the spacing below, not from the corners.
        for w in [
            &mut v.widgets.noninteractive,
            &mut v.widgets.inactive,
            &mut v.widgets.hovered,
            &mut v.widgets.active,
            &mut v.widgets.open,
        ] {
            w.corner_radius = egui::CornerRadius::ZERO;
            w.expansion = 0.0;
        }
        v.window_corner_radius = egui::CornerRadius::ZERO;
        v.menu_corner_radius = egui::CornerRadius::ZERO;
        v.window_shadow = egui::epaint::Shadow {
            offset: [0, 4],
            blur: 16,
            spread: 0,
            color: egui::Color32::from_black_alpha(if self.dark { 110 } else { 48 }),
        };
        v.popup_shadow = v.window_shadow;

        ctx.set_visuals(v);

        // ── metrics ─────────────────────────────────────────────────────────
        let mut style = (*ctx.style()).clone();
        let sp = &mut style.spacing;
        // The single worst thing about the first version: everything was
        // touching. Horizontal space between controls is bigger than vertical,
        // because a toolbar reads along its length and a form reads down it.
        sp.item_spacing = egui::vec2(8.0, 6.0);
        sp.button_padding = egui::vec2(10.0, 5.0);
        sp.window_margin = egui::Margin::same(12);
        sp.menu_margin = egui::Margin::same(6);
        sp.indent = 18.0;
        sp.interact_size = egui::vec2(40.0, scale + 12.0);
        sp.combo_width = 150.0;
        sp.text_edit_width = 220.0;
        sp.icon_width = scale + 3.0;
        sp.icon_width_inner = scale - 3.0;
        sp.scroll = egui::style::ScrollStyle {
            bar_width: 9.0,
            handle_min_length: 24.0,
            bar_inner_margin: 3.0,
            bar_outer_margin: 0.0,
            floating: false,
            ..egui::style::ScrollStyle::solid()
        };

        // Four sizes, not one. `Small` carries the counters and hints, `Body`
        // the chrome, `Monospace` the data and the SQL (at the same size as the
        // body so a grid and a label line up), `Heading` the section titles.
        use egui::{FontFamily, FontId, TextStyle};
        style.text_styles = [
            (TextStyle::Small, FontId::new(scale - 2.0, FontFamily::Proportional)),
            (TextStyle::Body, FontId::new(scale, FontFamily::Proportional)),
            (TextStyle::Button, FontId::new(scale, FontFamily::Proportional)),
            (TextStyle::Monospace, FontId::new(scale, FontFamily::Monospace)),
            (TextStyle::Heading, FontId::new(scale + 3.0, FontFamily::Proportional)),
        ]
        .into();
        ctx.set_style(style);
    }

    /// The row height the grid uses: the monospace line plus breathing room, so
    /// a cell is not a line of text wedged between two others.
    pub fn row_height(scale: f32) -> f32 {
        scale + 10.0
    }

    /// The base text size. `$LODE_FONT_SIZE` overrides it; the default is a
    /// little above a terminal's, because a window is read further away than a
    /// terminal pane and has no cell grid to help the eye.
    pub fn scale() -> f32 {
        std::env::var("LODE_FONT_SIZE")
            .ok()
            .and_then(|s| s.trim().parse::<f32>().ok())
            .filter(|v| (8.0..=32.0).contains(v))
            .unwrap_or(13.0)
    }

    /// The theme used when no file is found: the lvim "base dark" palette,
    /// hard-coded so a fresh install is readable before anything is generated.
    pub fn builtin() -> Theme {
        Theme {
            name: "LvimBaseDark (built in)".into(),
            style: "base_dark".into(),
            dark: true,
            // Byte for byte the generated LvimBase_dark, which is byte for byte
            // the editor's own groups. A built-in that differed from the file
            // would mean the application looked like one thing before a theme
            // was installed and another after.
            surface: Surface {
                base: "#20272b".into(),
                panel: "#1c2327".into(),
                raised: "#1e2529".into(),
                overlay: "#1c2327".into(),
                status: "#1e2529".into(),
                hover: "#2a373d".into(),
                selected: "#243037".into(),
                border: "#1e2529".into(),
            },
            text: Text {
                primary: "#5e8888".into(),
                muted: "#5b7d7e".into(),
                title: "#7d9753".into(),
                inverted: "#1a1f22".into(),
            },
            accent: Accent {
                primary: "#778e52".into(),
                secondary: "#129f87".into(),
                success: "#7d9753".into(),
                warning: "#da8950".into(),
                error: "#eb6157".into(),
                info: "#1b97cf".into(),
            },
            syntax: Syntax {
                keyword: "#448595".into(),
                string: "#7e965a".into(),
                number: "#e19556".into(),
                comment: "#5b7d7e".into(),
                function: "#3b6d8d".into(),
                operator: "#3a7280".into(),
                identifier: "#c6614d".into(),
            },
            match_: Match {
                bg: "#22292d".into(),
                fg: "#e19556".into(),
            },
            grid: Grid {
                header_bg: "#1e2529".into(),
                header_fg: "#539595".into(),
                row_alt: "#1a1f22".into(),
                selection_bg: "#22292d".into(),
                selection_fg: "#5e8888".into(),
                null_fg: "#5b7d7e".into(),
                line_nr: "#2a373d".into(),
            },
            palette: BTreeMap::new(),
        }
    }
}

/// The directories themes are looked for in, in order.
pub fn theme_dirs() -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Some(d) = std::env::var_os("LODE_THEME_DIR") {
        out.push(PathBuf::from(d));
    }
    if let Some(d) = std::env::var_os("XDG_CONFIG_HOME") {
        out.push(PathBuf::from(d).join("lode/themes"));
    }
    if let Some(h) = std::env::var_os("HOME") {
        out.push(PathBuf::from(h).join(".config/lode/themes"));
    }
    out
}

/// Every theme file found, by display name. The FIRST directory wins a name
/// clash, so `$LODE_THEME_DIR` can shadow an installed set — which is what a
/// person regenerating palettes needs.
pub fn discover() -> BTreeMap<String, PathBuf> {
    let mut found: BTreeMap<String, PathBuf> = BTreeMap::new();
    for dir in theme_dirs() {
        let Ok(entries) = std::fs::read_dir(&dir) else { continue };
        for e in entries.flatten() {
            let p = e.path();
            if p.extension().and_then(|s| s.to_str()) != Some("toml") {
                continue;
            }
            let Some(stem) = p.file_stem().and_then(|s| s.to_str()) else { continue };
            found.entry(stem.to_string()).or_insert(p);
        }
    }
    found
}

/// Load one theme file.
pub fn load(path: &std::path::Path) -> anyhow::Result<Theme> {
    let text = std::fs::read_to_string(path)?;
    let theme: Theme =
        toml::from_str(&text).map_err(|e| anyhow::anyhow!("{}: {e}", path.display()))?;
    Ok(theme)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hex_parses_and_falls_back() {
        assert_eq!(hex("#20272b", egui::Color32::RED), egui::Color32::from_rgb(0x20, 0x27, 0x2b));
        assert_eq!(hex("20272b", egui::Color32::RED), egui::Color32::from_rgb(0x20, 0x27, 0x2b));
        // One bad value costs one colour, not the theme.
        assert_eq!(hex("nope", egui::Color32::RED), egui::Color32::RED);
        assert_eq!(hex("#12345", egui::Color32::RED), egui::Color32::RED);
    }

    #[test]
    fn a_generated_theme_round_trips() {
        let toml_src = r##"
            name = "LvimBaseDark"
            style = "base_dark"
            dark = true
            [surface]
            base = "#20272b"
            panel = "#1c2327"
            raised = "#1e2529"
            overlay = "#1c2327"
            status = "#1e2529"
            hover = "#2a373d"
            selected = "#243037"
            border = "#1e2529"
            [text]
            primary = "#5e8888"
            muted = "#5b7d7e"
            title = "#7d9753"
            inverted = "#1a1f22"
            [accent]
            primary = "#6ba3c7"
            secondary = "#58a08f"
            success = "#8bb06a"
            warning = "#d8b36f"
            error = "#d75e52"
            info = "#6b9fd0"
            [grid]
            header_bg = "#2a3237"
            header_fg = "#cddada"
            row_alt = "#242b30"
            selection_bg = "#35505f"
            selection_fg = "#e3eded"
            null_fg = "#6f8080"
        "##;
        let t: Theme = toml::from_str(toml_src).expect("parses");
        assert_eq!(t.name, "LvimBaseDark");
        assert!(t.dark);
        assert_eq!(t.surface.base, "#20272b");
        // `syntax` and `palette` are optional: a theme without them still loads.
        assert!(t.syntax.keyword.is_empty());
        assert!(t.palette.is_empty());
    }

    /// Every REAL generated theme must parse and be complete. Pointed at the
    /// generator's output with `LODE_THEME_DIR`:
    ///
    ///     LODE_THEME_DIR=…/lvim-colorscheme/extras/lode cargo test -p lode-gui
    ///
    /// Skipped when that is not set, so the crate still tests without a
    /// colorscheme checkout — but when it IS set, a theme the generator can
    /// write and this client cannot read is a failure, not a warning.
    #[test]
    fn every_generated_theme_loads() {
        let Some(dir) = std::env::var_os("LODE_THEME_DIR") else {
            eprintln!("skipped: set LODE_THEME_DIR to the generator's output to check real themes");
            return;
        };
        let found = discover();
        assert!(!found.is_empty(), "no .toml themes in {dir:?}");
        for (name, path) in &found {
            let t = load(path).unwrap_or_else(|e| panic!("{name}: {e}"));
            assert_eq!(&t.name, name, "{name}: the file's `name` must match its stem");
            for (what, value) in [
                ("surface.base", &t.surface.base),
                ("surface.panel", &t.surface.panel),
                ("surface.raised", &t.surface.raised),
                ("surface.overlay", &t.surface.overlay),
                ("surface.status", &t.surface.status),
                ("surface.hover", &t.surface.hover),
                ("surface.selected", &t.surface.selected),
                ("surface.border", &t.surface.border),
                ("text.primary", &t.text.primary),
                ("text.muted", &t.text.muted),
                ("text.title", &t.text.title),
                ("text.inverted", &t.text.inverted),
                ("accent.primary", &t.accent.primary),
                ("accent.error", &t.accent.error),
                ("match.bg", &t.match_.bg),
                ("match.fg", &t.match_.fg),
                ("grid.header_bg", &t.grid.header_bg),
                ("grid.header_fg", &t.grid.header_fg),
                ("grid.row_alt", &t.grid.row_alt),
                ("grid.selection_bg", &t.grid.selection_bg),
                ("grid.selection_fg", &t.grid.selection_fg),
                ("grid.null_fg", &t.grid.null_fg),
                ("grid.line_nr", &t.grid.line_nr),
            ] {
                // A sentinel fallback here would mean an unparsed colour silently
                // becoming magenta in the window; fail instead.
                assert_ne!(
                    hex(value, egui::Color32::from_rgb(1, 2, 3)),
                    egui::Color32::from_rgb(1, 2, 3),
                    "{name}: {what} = {value:?} does not parse"
                );
            }
            assert!(!t.syntax.keyword.is_empty(), "{name}: the editor needs a syntax block");
            assert!(!t.palette.is_empty(), "{name}: the reference palette block is missing");
            // The theme is COPIED from the editor's groups, so the pair the
            // editor leaves equal must arrive equal: `Visual` sets no
            // foreground, which means selected text keeps `Normal.fg`. A
            // generator that "helped" by lifting one of them would break this.
            assert_eq!(
                t.grid.selection_fg, t.text.primary,
                "{name}: selected text must keep the body ink, as `Visual` does in the editor"
            );
            assert_eq!(
                t.dark,
                !t.style.ends_with("_light"),
                "{name}: `dark` disagrees with the style's own name"
            );
        }
        eprintln!("checked {} generated theme(s)", found.len());
    }

    /// The built-in theme must BE the generated LvimBase_dark, which is the
    /// editor's own groups. If they drift, the application looks like one thing
    /// before a theme is installed and another after.
    #[test]
    fn the_builtin_theme_is_the_editors_base_dark() {
        let t = Theme::builtin();
        assert_eq!(t.surface.base, "#20272b", "Normal.bg");
        assert_eq!(t.text.primary, "#5e8888", "Normal.fg — NOT lifted for contrast");
        assert_eq!(t.text.muted, "#5b7d7e", "Comment.fg");
        assert_eq!(t.surface.status, "#1e2529", "StatusLine.bg");
        assert_eq!(t.surface.hover, "#2a373d", "CursorLine.bg");
        assert_eq!(t.surface.selected, "#243037", "PmenuSel.bg");
        assert_eq!(t.grid.selection_bg, "#22292d", "Visual.bg");
        assert_eq!(t.grid.selection_fg, t.text.primary, "Visual sets no fg");
        assert_eq!(t.grid.line_nr, "#2a373d", "LineNr.fg");
    }

    #[test]
    fn the_builtin_theme_is_complete() {
        let t = Theme::builtin();
        for s in [
            &t.surface.base,
            &t.surface.panel,
            &t.surface.raised,
            &t.surface.status,
            &t.surface.selected,
            &t.text.primary,
            &t.text.title,
            &t.accent.primary,
            &t.grid.header_bg,
            &t.grid.null_fg,
            &t.grid.line_nr,
        ] {
            assert_eq!(s.len(), 7, "{s} is not #rrggbb");
            assert_ne!(hex(s, egui::Color32::RED), egui::Color32::RED, "{s} must parse");
        }
    }
}
